"use client";
/**
 * Checkbox — 21st.dev Geist implementation
 * Source: https://21st.dev / Geist Design System
 *
 * Uses --ds-gray-* / --ds-background-* CSS variables (registered in globals.css)
 * mapped to Tailwind via `geist-gray-*` / `geist-background-*` theme colors.
 */
import React from "react";
import { cn } from "../utils/cn";
import { CheckGlyph, IndeterminateGlyph } from "./control-glyph";
// =============================================================================
// Types
// =============================================================================
export interface CheckboxProps {
  checked?: boolean;
  defaultChecked?: boolean;
  onChange?: (checked: boolean) => void;
  disabled?: boolean;
  indeterminate?: boolean;
  children?: React.ReactNode;
  className?: string;
  id?: string;
  name?: string;
}
export interface CheckboxGroupProps {
  /** Accessible group label */
  label?: string;
  /** Layout direction */
  orientation?: "vertical" | "horizontal";
  children: React.ReactNode;
  className?: string;
}
// =============================================================================
// Checkbox indicator styles (Geist DS color logic)
// =============================================================================
const getInputClasses = (checked: boolean, disabled: boolean, indeterminate: boolean) => {
  let className =
    "relative border w-4 h-4 duration-200 rounded inline-flex items-center justify-center";
  if (disabled) {
    if (!checked || indeterminate) {
      className += " bg-geist-gray-100 border-geist-gray-500";
      className += indeterminate
        ? " stroke-geist-gray-500"
        : " fill-geist-gray-100 stroke-geist-gray-100";
    } else {
      className +=
        " bg-geist-gray-600 border-geist-gray-600 fill-geist-gray-600 stroke-geist-gray-100";
    }
  } else {
    if (!checked || indeterminate) {
      className += " bg-geist-background-100 border-geist-gray-700 group-hover:bg-geist-gray-200";
      className += indeterminate
        ? " stroke-geist-gray-700"
        : " fill-geist-background-100 stroke-geist-background-100 group-hover:stroke-geist-gray-200 group-hover:fill-geist-gray-200";
    } else {
      className +=
        " bg-geist-gray-1000 border-geist-gray-1000 fill-geist-gray-1000 stroke-geist-gray-100";
    }
  }
  return className;
};
// =============================================================================
// Checkbox
// =============================================================================
export const Checkbox = ({
  checked: controlledChecked,
  defaultChecked = false,
  onChange,
  disabled = false,
  indeterminate = false,
  children,
  className,
  id,
  name,
}: CheckboxProps) => {
  const [internalChecked, setInternalChecked] = React.useState(defaultChecked);
  const isControlled = controlledChecked !== undefined;
  const checked = isControlled ? controlledChecked : internalChecked;
  return (
    <label
      className={cn(
        "flex items-center text-[13px] font-sans group",
        disabled ? "text-geist-gray-500 cursor-not-allowed" : "text-geist-gray-1000 cursor-pointer",
        className,
      )}
    >
      <input
        id={id}
        name={name}
        disabled={disabled}
        type="checkbox"
        checked={checked}
        onChange={(e) => {
          if (!indeterminate) {
            if (!isControlled) {
              setInternalChecked(e.target.checked);
            }
            if (onChange) {
              onChange(e.target.checked);
            }
          }
        }}
        aria-label={typeof children === "string" ? children : "checkbox"}
        className="sr-only"
      />
      <span className={getInputClasses(checked, disabled, indeterminate)}>
        {indeterminate ? <IndeterminateGlyph /> : <CheckGlyph />}
      </span>
      {children && <span className="ml-2">{children}</span>}
    </label>
  );
};
// =============================================================================
// CheckboxGroup — simple layout wrapper
// =============================================================================
export function CheckboxGroup({
  label,
  orientation = "vertical",
  children,
  className,
}: CheckboxGroupProps) {
  return (
    // biome-ignore lint/a11y/useSemanticElements: ARIA pattern
    <div
      role="group"
      aria-label={label}
      className={cn(
        "flex",
        orientation === "vertical" ? "flex-col gap-3" : "flex-row flex-wrap gap-4",
        className,
      )}
    >
      {label && <span className="text-sm font-medium">{label}</span>}
      {children}
    </div>
  );
}
CheckboxGroup.displayName = "CheckboxGroup";
export default CheckboxGroup;

/**
 * Control glyphs — the tick and dash drawn inside a checkbox.
 *
 * These are deliberately NOT in `@nebutra/icons`. That package is generated:
 * `src/index.ts` and every file in `src/components/` are rewritten from
 * `src/svg/*.svg` by `pnpm --filter @nebutra/icons generate`, and the barrel it
 * writes declares its source as vercel.com/geist/icons. A hand-authored glyph
 * placed there would either be erased by the next generate run or become a
 * non-Geist file inside a set that claims to be pure Geist.
 *
 * They also cannot BE the Geist icons. `Check` is fill-based: a 16x16 outlined
 * path whose tick runs corner to corner with ~1px of padding and a nominal 1.5px
 * weight, tuned to stand alone on a text baseline. A checkbox tick is stroke-based
 * and must sit visibly inset from the box border, which means a different inset,
 * a different weight, and — critically — inheriting `stroke` and `fill` from the
 * control surface so the same glyph can be hidden by painting it in the box's own
 * colour. `<Check className="h-3 w-3" />` renders none of that.
 *
 * Geometry: authored in a 16-unit viewBox at 1:1 with the rendered 16px control,
 * so `strokeWidth` is also the rendered pixel weight. The tick spans x 4.8..11.2
 * (30% inset each side) and y 5.6..10, optically centred a hair high the way a
 * checkmark reads.
 *
 * Colour: no `fill` or `stroke` attribute is set. Both inherit, which is what lets
 * a control paint the tick in its own background to hide it (the unchecked state)
 * without unmounting it. A control that wants the triangle interior transparent
 * instead passes `fill="none"`.
 */
import type * as React from "react";

export interface ControlGlyphProps extends React.SVGProps<SVGSVGElement> {
  /** Rendered size in px. The viewBox is 16, so 16 keeps stroke width at 1:1. */
  size?: number | string;
}

const DEFAULT_STROKE_WIDTH = 1.6;

/** Checkmark for a checked checkbox. */
export function CheckGlyph({
  size = 16,
  width,
  height,
  strokeWidth = DEFAULT_STROKE_WIDTH,
  ...props
}: ControlGlyphProps) {
  return (
    <svg
      aria-hidden="true"
      className="shrink-0"
      viewBox="0 0 16 16"
      width={width ?? size}
      height={height ?? size}
      {...props}
    >
      <path
        d="M11.2 5.6L6.8 10L4.8 8"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={strokeWidth}
      />
    </svg>
  );
}

/** Horizontal dash for a partially-checked (indeterminate) checkbox. */
export function IndeterminateGlyph({
  size = 16,
  width,
  height,
  strokeWidth = DEFAULT_STROKE_WIDTH,
  ...props
}: ControlGlyphProps) {
  return (
    <svg
      aria-hidden="true"
      className="shrink-0"
      viewBox="0 0 16 16"
      width={width ?? size}
      height={height ?? size}
      {...props}
    >
      <line
        x1="4"
        x2="12"
        y1="8"
        y2="8"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={strokeWidth}
      />
    </svg>
  );
}
